const threadSLACompleteness = "SLA predicates defer a lead while relevant response evidence is unavailable; this is a boolean completeness probe, not activity content or conversation membership, and the statement census retains its exact source proof"

const (
	threadPrivacyMaintenance        = "statutory retention and erasure must reach unavailable source rows to preserve or remove their content; this path is maintenance, not a conversation view, and must not infer a repaired partition from a temporary key"
	threadEvidenceMaintenance       = "source provenance and privacy maintenance operate on the named message independently of its conversation partition; skipping an unavailable row would lose the evidence or leave derived data wider than its source"
	threadOriginalRepairMaintenance = "the retained repair reconstructs provider evidence on individual source rows and advances a durable cursor; excluding a temporarily unavailable row would permanently miss its correction, and it neither publishes nor decides a conversation partition"
	threadAuditMaintenance          = "reads immutable audit evidence or a refusal derived from it, independently of the activity's current partition; no partially repaired conversation or thread membership is returned, and any activity mutation still passes its ordinary write boundary"
	threadRepairMaintenance         = "the authorized thread planner and owner apply seams must read and rewrite the staged component while it is unavailable; the repair publishes all partitions through one phase transition after its bounded work finishes"
	threadMembershipFragment        = "returns membership IDs without activity content or thread keys; ordinary readers compose their own availability predicate on the outer activity, while maintenance retains the IDs needed to retract derived data"
)

const threadSubjectAccessMaintenance = "an authorized subject-access export must retain the subject's authored evidence during a temporary processing barrier; it applies the subject's own scope and labels unpublished or invalidated work rather than publishing it as a conversation decision"

