const (
	threadReceiptMaintenance      = "records delivery lifecycle evidence after an attempt or provider response, without interpreting conversation membership; withholding a receipt or failure could retransmit a message already accepted, while Stage, Load and MarkInFlight enforce availability before transmission"
	threadCaptureBirthMaintenance = "runs inside authorized provider capture under the thread merge lock to maintain the named source row; it must preserve provider evidence while the repair stages it, and the repair observes every changed activity version before publication"
	threadSubjectMergeMaintenance = "repoints a retiring subject's retained evidence onto its survivor independently of conversation membership; it must preserve consent, delivery and invalidation history even while the underlying source rows are unavailable"
)

